  function aggregateWeekRequirements(){const map=new Map();for(const d of weekDates()){const day=state.mealPlan[dateKey(d)]||{};for(const slot of MEAL_SLOTS){const item=day[slot],r=getRecipe(item?.recipeId);if(!r)continue;const factor=(Number(item.servings)||Number(r.servings)||1)/(Number(r.servings)||1);for(const line of r.ingredients||[]){const p=parseIngredient(line);if(!p.name)continue;const key=`${p.name}|${p.baseUnit||'unknown'}`,entry=map.get(key)||{name:p.name,baseUnit:p.baseUnit||'',displayUnit:p.displayUnit||p.unit||'',qty:0,known:true,sources:new Set(),example:line};if(Number.isFinite(p.baseQty))entry.qty+=p.baseQty*factor;else entry.known=false;entry.sources.add(r.title);map.set(key,entry)}}}return [...map.values()]}
  function pantryAvailability(req){const matches=state.pantry.filter(p=>ingredientMatches(p.name,req.name));let total=0,compatible=false,packageItem=matches.find(p=>p.packageSize)||matches[0];for(const p of matches){const b=toBaseQty(p.quantity,p.unit);if(b&&req.baseUnit&&b.baseUnit===req.baseUnit){total+=b.value;compatible=true}else if(!req.baseUnit&&Number(p.quantity)>0){compatible=true;total+=Number(p.quantity)}}return{matches,total,compatible,packageItem}}
  function buildGroceryFromRequirement(req){const avail=pantryAvailability(req);if(req.known&&Number.isFinite(req.qty)&&req.baseUnit&&avail.compatible&&avail.total>=req.qty-1e-9)return null;if(!req.known&&avail.matches.some(p=>Number(p.quantity)>0||p.staple))return null;const shortage=req.known&&Number.isFinite(req.qty)?Math.max(0,req.qty-(avail.compatible?avail.total:0)):NaN;const pkg=parsePackageSize(avail.packageItem?.packageSize||'');let text=req.example||req.name,packageNote='',purchaseQty=NaN,purchaseUnit=req.baseUnit||'',titleUnit='';if(Number.isFinite(shortage)&&shortage>0){if(pkg&&pkg.baseUnit===req.baseUnit&&pkg.baseQty>0){const count=Math.max(1,Math.ceil(shortage/pkg.baseQty)),bought=count*pkg.baseQty,extra=Math.max(0,bought-shortage);text=`${count} × ${avail.packageItem.packageSize} ${req.name}`;packageNote=`Need about ${prettyQty(shortage)} ${req.baseUnit}${extra>0?` · ~${prettyQty(extra)} ${req.baseUnit} extra`:''}`;purchaseQty=bought;purchaseUnit=req.baseUnit}else{const du=req.displayUnit||req.baseUnit,dd=unitDef(du),shown=dd&&dd[0]===req.baseUnit?fromBaseQty(shortage,du):shortage;titleUnit=req.baseUnit==='count'?'':du;text=`${prettyQty(shown)} ${titleUnit} ${req.name}`.replace(/\s+/g,' ').trim();purchaseQty=shortage;purchaseUnit=req.baseUnit}}return{text,ingredientName:req.name,category:groceryCategory(req.name),source:'week-plan',sourceRecipes:[...req.sources],packageNote,purchaseQty:Number.isFinite(purchaseQty)?purchaseQty:null,purchaseUnit,purchaseDisplayUnit:req.displayUnit||purchaseUnit}}
  function planAroundExpiry(){const exp=expiringIngredientNames(),ctx=createMatchContext();if(!exp.length){toast('Nothing in your pantry is expiring soon');return}const pick=state.recipes.map(r=>({r,m:recipeMatch(r,[],ctx)})).filter(x=>x.m.useSoon>0).sort((a,b)=>b.m.useSoon-a.m.useSoon||b.m.percent-a.m.percent||totalTime(a.r)-totalTime(b.r))[0];if(!pick){toast('No saved recipe uses the expiring ingredients yet');return}planRecipeNextAvailable(pick.r.id)}
  function renderParallelTimeline(){const date=$('#parallelDate')?.value||dateKey(new Date()),time=$('#parallelTime')?.value||state.settings.defaultDinnerTime||'19:00',out=$('#parallelOutput');if(!out)return;const plan=state.mealPlan[date]||{},recipes=activeMealSlots().map(slot=>({slot,item:plan[slot],r:getRecipe(plan[slot]?.recipeId)})).filter(x=>x.r);if(!recipes.length){out.innerHTML='<p class="muted" style="margin-top:10px">Plan saved recipes on that date first.</p>';return}const [hh,mm]=time.split(':').map(Number),ready=parseDate(date)||new Date();ready.setHours(hh,mm,0,0);const fmt=d=>d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}),rows=recipes.map(x=>{const prep=Number(x.r.prep||0),cook=Number(x.r.cook||0),start=new Date(ready.getTime()-(prep+cook)*60000),cookStart=new Date(ready.getTime()-cook*60000);return{...x,start,cookStart}}).sort((a,b)=>a.start-b.start);out.innerHTML=`<div class="detail-section"><h3>Everything ready by ${fmt(ready)}</h3>${rows.map(x=>`<div class="timeline-card"><div class="timeline-card-head"><div><b>${foodEmoji(x.r)} ${esc(x.r.title)}</b><small class="muted">${esc(x.slot)} · ${totalTime(x.r)} min total</small></div><strong>${fmt(x.start)}</strong></div><small class="muted">Prep ${fmt(x.start)} · cook ${fmt(x.cookStart)} · serve ${fmt(ready)}</small></div>`).join('')}</div>`}
  function renderIngredientJourney(){const term=($('#journeyIngredientInput')?.value||'').trim(),out=$('#journeyOutput');if(!out)return;if(!term){out.innerHTML='<p class="muted" style="margin-top:10px">Type an ingredient to trace it through your week and recipe library.</p>';return}const planned=[];weekDates().forEach(d=>{const day=state.mealPlan[dateKey(d)]||{};for(const slot of MEAL_SLOTS){const r=getRecipe(day[slot]?.recipeId);if(r&&(r.ingredients||[]).some(i=>ingredientMatches(i,term)))planned.push({date:d,slot,r})}});const library=state.recipes.filter(r=>(r.ingredients||[]).some(i=>ingredientMatches(i,term))).slice(0,20);out.innerHTML=`<div class="detail-section"><h3>🥕 ${esc(term)}</h3><p class="muted">This week</p>${planned.length?planned.map(x=>`<div class="journey-use"><time>${esc(formatShortDate(x.date))}</time><button class="text-btn" data-recipe-id="${x.r.id}">${esc(x.r.title)}</button><small class="muted">${esc(x.slot)}</small></div>`).join(''):'<p class="muted">Not used in this visible week.</p>'}<p class="muted" style="margin-top:12px">Saved recipes</p>${library.length?library.map(r=>`<button class="list-card" data-recipe-id="${r.id}"><span class="emoji">${foodEmoji(r)}</span><span class="content"><b>${esc(r.title)}</b><small>${totalTime(r)} min</small></span><span class="meta">›</span></button>`).join(''):'<p class="muted">No saved recipe uses it yet.</p>'}</div>`}
  function preparePantryDeductions(r){const byPantry=new Map();for(const line of r.ingredients||[]){const pi=parseIngredient(line),p=state.pantry.find(x=>Number(x.quantity)>0&&ingredientMatches(x.name,pi.name));if(!p)continue;let amount=1;if(Number.isFinite(pi.baseQty)){const pb=toBaseQty(p.quantity,p.unit),def=unitDef(p.unit);if(pb&&def&&pb.baseUnit===pi.baseUnit)amount=fromBaseQty(pi.baseQty,p.unit)}amount=Math.min(Number(p.quantity)||0,Math.max(.01,Number(amount)||1));const ex=byPantry.get(p.id);if(ex)ex.amount=Math.min(Number(p.quantity)||0,ex.amount+amount);else byPantry.set(p.id,{pantryId:p.id,name:p.name,amount,unit:p.unit||'',before:Number(p.quantity)||0})}pendingPantryDeductions=[...byPantry.values()];return pendingPantryDeductions}
  function openPantryDeductionReview(r){const list=preparePantryDeductions(r);if(!list.length)return false;$('#pantryDeductionList').innerHTML=list.map(d=>`<label class="deduction-row"><input type="checkbox" data-deduct-id="${d.pantryId}" checked><span><b>${esc(d.name)}</b><small>${prettyQty(d.before)} ${esc(d.unit)} currently</small></span><span class="amount-box"><input type="number" data-deduct-amount="${d.pantryId}" min="0" max="${d.before}" step="0.01" value="${prettyQty(d.amount)}"><span>${esc(d.unit)}</span></span></label>`).join('');openDialog($('#pantryDeductionDialog'));return true}
  function renderActivity(){const purchases=[...state.purchaseHistory].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,100),uses=[...state.useHistory].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,100);const row=(x,icon,verb)=>`<div class="activity-row"><span>${icon}</span><span><b>${esc(x.item||x.name||'Item')}</b><small>${esc(verb)}${x.amount!=null?` · ${prettyQty(Number(x.amount))} ${esc(x.unit||'')}`:''}</small></span><time>${esc(formatDateTime(x.date))}</time></div>`;$('#purchaseHistoryList').innerHTML=purchases.length?purchases.map(x=>row(x,'🧺','Added to pantry')).join(''):emptyCard('Nothing bought has been logged yet. Checked groceries appear here only after you move them to Pantry.');$('#pantryUseHistoryList').innerHTML=uses.length?uses.map(x=>row(x,'🥣','Used from pantry')).join(''):emptyCard('No pantry use recorded yet. Bento only logs amounts you confirm after cooking.')}

  function navigate(view,pushHash=true){if(view==='more')view='home';if(!document.querySelector(`.view[data-view="${view}"]`))view='home';closeMenu();if(currentView!==view)previousView=currentView;currentView=view;$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===view));$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));if(pushHash)history.replaceState(null,'',`#${view}`);window.scrollTo(0,0);$('#mainContent')?.focus({preventScroll:true});try{renderCurrentView();renderGlobalBadges()}catch(err){console.error('Bento navigation render error',err);if(view!=='home'){currentView='home';$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view==='home'));renderHome()}toast('Bento recovered safely.') }}
  function back(){navigate(previousView||'home')}
  function openMenu(){const menu=$('#appMenu'),backdrop=$('#menuBackdrop');if(!menu||!backdrop)return;backdrop.hidden=false;requestAnimationFrame(()=>{menu.classList.add('open');backdrop.classList.add('open')});menu.setAttribute('aria-hidden','false');$('#menuButton')?.setAttribute('aria-expanded','true');document.body.classList.add('menu-open')}
  function closeMenu(){const menu=$('#appMenu'),backdrop=$('#menuBackdrop');if(!menu||!backdrop)return;menu.classList.remove('open');backdrop.classList.remove('open');menu.setAttribute('aria-hidden','true');$('#menuButton')?.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open');setTimeout(()=>{if(!backdrop.classList.contains('open'))backdrop.hidden=true},210)}

  function updateGroceryCounters(){const unchecked=state.grocery.reduce((n,g)=>n+(!g.checked?1:0),0),checked=state.grocery.length-unchecked,estimate=state.grocery.reduce((n,g)=>n+(Number(g.price)||0),0);if($('#groceryUnchecked'))$('#groceryUnchecked').textContent=unchecked;if($('#groceryChecked'))$('#groceryChecked').textContent=checked;if($('#groceryEstimate')){try{$('#groceryEstimate').textContent=estimate?estimate.toLocaleString(undefined,{style:'currency',currency:state.settings.currency||'PHP'}):'—'}catch{$('#groceryEstimate').textContent=estimate?String(estimate):'—'}}const badge=$('#groceryNavBadge');if(badge){badge.textContent=unchecked>99?'99+':String(unchecked);badge.classList.toggle('hidden',unchecked===0)}}
  function renderGlobalBadges(){
    const unchecked=state.grocery.reduce((n,g)=>n+(!g.checked?1:0),0);
    if($('#groceryCountQuick'))$('#groceryCountQuick').textContent=`${unchecked} item${unchecked===1?'':'s'}`;
    if($('#pantryCountQuick'))$('#pantryCountQuick').textContent=`${state.pantry.length} item${state.pantry.length===1?'':'s'}`;
    updateGroceryCounters();
  }
  function renderGreeting(){const h=new Date().getHours(),g=h<12?'Good morning':h<18?'Good afternoon':'Good evening',name=(state.settings.displayName||'').trim();$('#greetingText').textContent=`${g}${name?`, ${name}`:''} ✿`}
  function renderHome(){
    renderGreeting();const firstRun=isFirstRun();$('#firstRunWelcome')?.classList.toggle('hidden',!firstRun);
    const today=dateKey(new Date()),plan=state.mealPlan[today]||{},slots=activeMealSlots();
    $('#todayMeals').innerHTML=slots.map(slot=>{const item=plan[slot];let title='Nothing planned',sub='Tap to add';if(item?.recipeId){const r=getRecipe(item.recipeId);if(r){title=r.title;sub=`${totalTime(r)} min · ${item.servings||r.servings||2} servings${item.extraPortions?` · +${item.extraPortions} leftover`:''}`}}else if(item?.custom){title=item.custom;sub=item.prepNote||'Custom meal'}return `<button class="meal-card" data-meal-date="${today}" data-meal-slot="${slot}"><span class="meal-slot">${slot}</span><span class="meal-main"><b>${esc(title)}</b><small>${esc(sub)}</small></span><span class="arrow">›</span></button>`}).join('');
    const prep=tomorrowPrepItems(),showPrep=!firstRun&&state.settings.showTomorrowPrep!==false&&prep.length>0;$('#tomorrowPrepHeading')?.classList.toggle('hidden',!showPrep);$('#tomorrowPrep')?.classList.toggle('hidden',!showPrep);if(showPrep)$('#tomorrowPrep').innerHTML=prep.length?prep.map(x=>`<div class="prep-card"><span>${x.icon}</span><div><b>${esc(x.title)}</b><small>${esc(x.sub)}</small></div></div>`).join(''):emptyCard('Nothing needs advance prep for tomorrow.');
    $('#homeQuickActions')?.classList.toggle('hidden',!firstRun&&state.settings.showHomeQuickActions===false);
    const weekMeals=weekDates(0).reduce((n,d)=>n+Object.keys(state.mealPlan[dateKey(d)]||{}).length,0),expiring=state.pantry.filter(p=>{const d=daysUntil(p.expiry);return d>=0&&d<=expiryWindow()}).length,monthStart=new Date();monthStart.setDate(1);monthStart.setHours(0,0,0,0);const cookedMonth=state.history.filter(h=>new Date(h.date)>=monthStart).length;
    $('#homeStats').innerHTML=`<div class="stat-card"><strong>${weekMeals}</strong><small>meals planned</small></div><div class="stat-card"><strong>${cookedMonth}</strong><small>cooked this month</small></div><div class="stat-card"><strong>${expiring}</strong><small>use soon</small></div>`;
    const showStats=!firstRun&&state.settings.showHomeStats!==false;$('#homeStats')?.classList.toggle('hidden',!showStats);$('#homeStatsHeading')?.classList.toggle('hidden',!showStats);renderAttention();
    const showFav=!firstRun&&state.settings.showHomeFavorites!==false;$('#homeFavorites')?.classList.toggle('hidden',!showFav);$('#homeFavoritesHeading')?.classList.toggle('hidden',!showFav);if(showFav){const favs=state.recipes.filter(r=>r.favorite).slice(0,6);$('#homeFavorites').innerHTML=favs.length?favs.map(recipeMini).join(''):emptyCard('Heart recipes you love and they’ll appear here.','Browse recipes','go-recipes')}
  }

  function renderAttention(){const expiring=state.pantry.filter(p=>{const d=daysUntil(p.expiry);return d>=0&&d<=expiryWindow()}).sort((a,b)=>daysUntil(a.expiry)-daysUntil(b.expiry));const low=state.pantry.filter(p=>p.lowStock),unchecked=state.grocery.filter(g=>!g.checked).length,leftSoon=state.leftovers.filter(l=>{const d=daysUntil(l.useBy);return d>=0&&d<=2}).length;const c=[];if(expiring.length)c.push(`<button class="attention-card" data-view-link="smart" data-auto-tool="rescue"><span class="dot"></span><div><b>${expiring.length} pantry item${expiring.length>1?'s':''} expiring soon</b><small>${esc(expiring.slice(0,3).map(x=>x.name).join(', '))}</small></div><span>›</span></button>`);if(leftSoon)c.push(`<button class="attention-card" data-view-link="leftovers"><span class="dot"></span><div><b>${leftSoon} leftover${leftSoon>1?'s':''} to use soon</b><small>Eat, freeze or plan them next</small></div><span>›</span></button>`);if(low.length)c.push(`<button class="attention-card" data-nav="pantry"><span class="dot"></span><div><b>${low.length} low-stock item${low.length>1?'s':''}</b><small>Restock when convenient</small></div><span>›</span></button>`);if(unchecked)c.push(`<button class="attention-card" data-nav="grocery"><span class="dot"></span><div><b>${unchecked} grocery item${unchecked>1?'s':''} waiting</b><small>Open your shopping list</small></div><span>›</span></button>`);$('#attentionCards').innerHTML=c.join('')||emptyCard('Nothing urgent right now. Your kitchen is looking tidy ✿')}
  function recipeMini(r){return `<button class="mini-recipe" data-recipe-id="${r.id}"><b>${foodEmoji(r)} ${esc(r.title)}</b><small>${totalTime(r)} min · ${esc(r.category||'Other')}</small></button>`}

  function renderPlan(){const dates=weekDates(),todayKey=dateKey(new Date());$('#weekLabel').textContent=`${formatShortDate(dates[0])} – ${formatShortDate(dates[6])}`;$('#weekDays').innerHTML=dates.map(d=>`<div class="day-pill ${dateKey(d)===todayKey?'today':''}"><b>${d.toLocaleDateString(undefined,{weekday:'short'})}</b><span>${d.getDate()}</span></div>`).join('');$('#mealPlanGrid').innerHTML=dates.map(d=>{const key=dateKey(d),p=state.mealPlan[key]||{};return `<article class="plan-day"><div class="plan-day-head"><b>${esc(formatLongDate(d))}</b><small>${key===todayKey?'Today':''}</small></div>${activeMealSlots().map(slot=>{const item=p[slot];let main='Add meal',sub='';if(item?.recipeId){const r=getRecipe(item.recipeId);if(r){main=r.title;sub=`${totalTime(r)} min${item.prepNote?` · ${item.prepNote}`:''}${item.extraPortions?` · +${item.extraPortions} leftover${item.extraPortions===1?'':'s'}`:''}`}}else if(item?.custom){main=item.custom;sub=item.prepNote||'Custom meal'}return `<button class="plan-slot" data-meal-date="${key}" data-meal-slot="${slot}"><span>${slot}</span><div><b>${esc(main)}</b>${sub?`<small>${esc(sub)}</small>`:''}</div><i class="plan-add">${item?'›':'+'}</i></button>`}).join('')}</article>`}).join('')}

  function recipeCard(r){return `<article class="recipe-card"><button class="heart-btn" data-favorite="${r.id}" aria-label="Favorite">${r.favorite?'♥':'♡'}</button><button class="recipe-open" data-recipe-id="${r.id}"><div class="thumb">${foodEmoji(r)}</div><div class="body"><b>${esc(r.title)}</b><small>${totalTime(r)} min · ${r.servings||2} servings · ${r.cleanup===1?'1 pan':r.cleanup===3?'project':'easy cleanup'}</small><div class="badge-row"><span class="badge">${esc(r.category||'Other')}</span>${r.cuisine?`<span class="badge">${esc(r.cuisine)}</span>`:''}${r.collection?`<span class="badge">${esc(r.collection)}</span>`:''}${r.freezer==='yes'?'<span class="badge">❄ freezer</span>':''}</div></div></button></article>`}
  function renderRecipeFilters(){const cats=['All','Favorites','Quick','Low Cleanup','Freezer Friendly',...[...new Set(state.recipes.map(r=>r.category).filter(Boolean))]];$('#recipeFilters').innerHTML=cats.map(c=>`<button class="chip ${recipeFilter===c?'active':''}" data-recipe-filter="${esc(c)}">${esc(c)}</button>`).join('')}
  function filteredRecipes(){const q=($('#recipeSearch')?.value||'').trim().toLowerCase();let list=[...state.recipes];if(recipeFilter==='Favorites')list=list.filter(r=>r.favorite);else if(recipeFilter==='Quick')list=list.filter(r=>totalTime(r)<=30);else if(recipeFilter==='Low Cleanup')list=list.filter(r=>Number(r.cleanup||2)<=1);else if(recipeFilter==='Freezer Friendly')list=list.filter(r=>r.freezer==='yes');else if(recipeFilter.startsWith('Collection:'))list=list.filter(r=>(r.collection||'')===recipeFilter.slice(11));else if(recipeFilter!=='All')list=list.filter(r=>r.category===recipeFilter);if(q)list=list.filter(r=>`${r.title} ${r.cuisine} ${r.category} ${r.collection} ${(r.ingredients||[]).join(' ')} ${r.notes||''} ${r.equipment||''}`.toLowerCase().includes(q));const sort=$('#recipeSort')?.value||'newest';if(sort==='name')list.sort((a,b)=>a.title.localeCompare(b.title));else if(sort==='quick')list.sort((a,b)=>totalTime(a)-totalTime(b));else if(sort==='favorite')list.sort((a,b)=>Number(b.favorite)-Number(a.favorite)||a.title.localeCompare(b.title));else if(sort==='cooked'){const counts=cookCountMap();list.sort((a,b)=>(counts.get(b.id)||0)-(counts.get(a.id)||0)||a.title.localeCompare(b.title));}else list.sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));return list}
  function renderRecipes(){if(currentView==='favorites'){const f=state.recipes.filter(r=>r.favorite),fv=f.slice(0,recipeRenderLimit);$('#favoritesGrid').innerHTML=f.length?fv.map(recipeCard).join('')+(f.length>fv.length?`<div class="load-more-wrap"><button class="soft-btn load-more-btn" data-load-more-recipes>Show more · ${f.length-fv.length} remaining</button></div>`:''):emptyCard('No favorites yet. Tap ♡ on a recipe you love.','Browse recipes','go-recipes');return}renderRecipeFilters();const list=filteredRecipes(),visible=list.slice(0,recipeRenderLimit);$('#recipeGrid').innerHTML=list.length?visible.map(recipeCard).join('')+(list.length>visible.length?`<div class="load-more-wrap"><button class="soft-btn load-more-btn" data-load-more-recipes>Show more · ${list.length-visible.length} remaining</button></div>`:''):emptyCard(state.recipes.length?'No recipes match this search.':'Your recipe book is empty. Add your first recipe to begin.','Add recipe','add-recipe')}

  function renderPantry(){const opts=['All','Expiring Soon','Low Stock','Fridge','Freezer','Pantry','Spice Rack','Other'];$('#pantryFilters').innerHTML=opts.map(c=>`<button class="chip ${pantryFilter===c?'active':''}" data-pantry-filter="${esc(c)}">${esc(c)}</button>`).join('');const q=($('#pantrySearch')?.value||'').trim().toLowerCase();let list=state.pantry.filter(p=>!q||`${p.name} ${p.location} ${p.store||''}`.toLowerCase().includes(q));if(pantryFilter==='Expiring Soon')list=list.filter(p=>{const d=daysUntil(p.expiry);return d>=0&&d<=expiryWindow()});else if(pantryFilter==='Low Stock')list=list.filter(p=>p.lowStock);else if(pantryFilter!=='All')list=list.filter(p=>p.location===pantryFilter);if(pantrySort==='expiry')list.sort((a,b)=>(daysUntil(a.expiry)-daysUntil(b.expiry))||a.name.localeCompare(b.name));else list.sort((a,b)=>a.name.localeCompare(b.name));$('#pantrySortButton').textContent=pantrySort==='expiry'?'Expiry':'A–Z';const visible=list.slice(0,pantryRenderLimit);$('#pantryList').innerHTML=list.length?visible.map(p=>{const due=daysUntil(p.expiry);let status='';if(Number.isFinite(due)){if(due<0)status='<span class="status-pill warn">Expired</span>';else if(due<=expiryWindow())status=`<span class="status-pill warn">${due===0?'Today':`${due}d left`}</span>`;else status=`<span class="status-pill">${due}d left</span>`}if(p.lowStock)status+='<span class="status-pill warn">Low stock</span>';if(p.staple)status+='<span class="status-pill">Staple</span>';return `<button class="list-card" data-pantry-id="${p.id}"><span class="emoji">${pantryEmoji(p)}</span><span class="content"><b>${esc(p.name)}</b><small>${esc(`${p.quantity??''} ${p.unit||''}`.trim()||'Quantity not set')} · ${esc(p.location)}${p.opened?` · opened ${esc(p.opened)}`:''}</small>${status}</span><span class="meta">›</span></button>`}).join('')+(list.length>visible.length?`<div class="load-more-wrap"><button class="soft-btn load-more-btn" data-load-more-pantry>Show more · ${list.length-visible.length} remaining</button></div>`:''):emptyCard(state.pantry.length?'No pantry items match this filter.':'Your pantry is empty. Add what you already have at home.','Add pantry item','add-pantry')}

  function grocerySourceLabel(g){if(!g.source)return'';if(g.source.startsWith('recipe:')){const r=getRecipe(g.source.slice(7));return r?`For ${r.title}`:''}if(g.source==='week-plan')return g.sourceRecipes?.length?`For ${g.sourceRecipes.slice(0,2).join(' + ')}${g.sourceRecipes.length>2?'…':''}`:'From meal plan';if(g.source==='low-stock')return'Low stock';if(g.source==='recurring-staple')return'Recurring staple';return''}

  function renderGrocery(){updateGroceryCounters();const groups={};[...state.grocery].sort((a,b)=>Number(a.checked)-Number(b.checked)||(a.text||'').localeCompare(b.text||'')).forEach(g=>{const cat=g.category||groceryCategory(g.text);(groups[cat]||=[]).push(g)});const order=['Produce','Protein','Dairy & Eggs','Pantry','Other'];$('#groceryList').innerHTML=state.grocery.length?order.filter(k=>groups[k]?.length).map(cat=>`<section class="grocery-group"><h3>${cat}</h3>${groups[cat].map(g=>`<div class="grocery-item ${g.checked?'checked':''}"><input type="checkbox" data-grocery-check="${g.id}" ${g.checked?'checked':''} aria-label="Check ${esc(g.text)}"><span>${esc(g.text)}${grocerySourceLabel(g)?`<small class="muted"> · ${esc(grocerySourceLabel(g))}</small>`:''}${g.packageNote?`<small class="package-note">${esc(g.packageNote)}</small>`:''}</span><button data-grocery-delete="${g.id}" aria-label="Delete">×</button></div>`).join('')}</section>`).join(''):emptyCard('Your grocery list is empty. Add an item or generate one from this week’s meal plan.')}

  function pantryAvailableNames(extra=[]){return [...state.pantry.map(p=>p.name),...extra].filter(Boolean)}
  function expiringIngredientNames(){return state.pantry.filter(p=>{const d=daysUntil(p.expiry);return d>=0&&d<=expiryWindow()}).map(p=>p.name)}
  function createMatchContext(extra=[]){return{avail:pantryAvailableNames(extra),expiring:expiringIngredientNames()}}
  function recipeMatch(recipe,extra=[],context=null){const ctx=context||createMatchContext(extra),ings=(recipe.ingredients||[]).filter(Boolean),missing=ings.filter(i=>!ctx.avail.some(a=>ingredientMatches(i,a))),matched=ings.length-missing.length,useSoon=ings.filter(i=>ctx.expiring.some(a=>ingredientMatches(i,a))).length;return{matched,total:ings.length,missing,percent:ings.length?Math.round(matched/ings.length*100):0,useSoon}}
  function renderCookMatches(){const extras=($('#customCookIngredients')?.value||'').split(',').map(s=>s.trim()).filter(Boolean),ctx=createMatchContext(extras);let results=state.recipes.map(r=>({recipe:r,...recipeMatch(r,extras,ctx)}));if(matchFilter==='perfect')results=results.filter(x=>x.missing.length===0);else if(matchFilter==='almost')results=results.filter(x=>x.missing.length<=2);else if(matchFilter==='use-soon')results=results.filter(x=>x.useSoon>0);results.sort((a,b)=>b.useSoon-a.useSoon||b.percent-a.percent||a.missing.length-b.missing.length||totalTime(a.recipe)-totalTime(b.recipe));const visible=results.slice(0,matchRenderLimit);$('#cookMatchList').innerHTML=results.length?visible.map(x=>`<article class="match-card"><div class="match-card-head"><div><b>${foodEmoji(x.recipe)} ${esc(x.recipe.title)}</b><small class="muted">${x.matched}/${x.total} available · ${totalTime(x.recipe)} min${x.useSoon?` · rescues ${x.useSoon}`:''}</small></div><strong>${x.percent}%</strong></div><div class="match-bar"><i style="width:${x.percent}%"></i></div><div class="missing">${x.missing.length?`Missing: ${esc(x.missing.join(', '))}`:'Perfect match — you have everything listed.'}</div><div class="action-row" style="margin-top:10px;margin-bottom:0"><button class="soft-btn" data-recipe-id="${x.recipe.id}">View</button><button class="soft-btn" data-plan-next="${x.recipe.id}">Plan</button>${x.missing.length?`<button class="soft-btn" data-add-missing="${x.recipe.id}">Add missing</button>`:''}</div></article>`).join('')+(results.length>visible.length?`<div class="load-more-wrap"><button class="soft-btn load-more-btn" data-load-more-matches>Show more · ${results.length-visible.length} remaining</button></div>`:''):emptyCard(state.recipes.length?'No recipes match this filter.':'Add some recipes first, then Bento can match them to your pantry.','Add recipe','add-recipe')}

  function smartFilteredRecipes(){const max=Number($('#smartTime')?.value||0),energy=$('#smartEnergy')?.value||'any',equipment=$('#smartEquipment')?.value||'any';return state.recipes.filter(r=>(!max||totalTime(r)<=max)&&(energy==='any'||r.energy===energy)&&(equipment==='any'||(equipment==='none'?!((r.equipment||'').trim()):(r.equipment||'').toLowerCase().includes(equipment))))}
  function smartRecipeResult(title,list,empty='No recipes match those settings yet.'){return `<div class="smart-card"><h3>${esc(title)}</h3>${list.length?list.slice(0,8).map(r=>`<button class="list-card" data-recipe-id="${r.id}"><span class="emoji">${foodEmoji(r)}</span><span class="content"><b>${esc(r.title)}</b><small>${totalTime(r)} min · ${r.cleanup===1?'1 pan':'cleanup '+r.cleanup}/3 · ${r.energy} effort</small></span><span class="meta">›</span></button>`).join(''):`<p class="muted">${esc(empty)}</p>`}</div>`}
  function recipeOptions(selected=''){return `<option value="">Choose recipe…</option>`+[...state.recipes].sort((a,b)=>a.title.localeCompare(b.title)).map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(r.title)}</option>`).join('')}
  function renderSmart(){$$('[data-smart-tool]').forEach(b=>b.classList.toggle('active',b.dataset.smartTool===activeSmartTool));const box=$('#smartResult');if(!state.recipes.length && !['prep','batch','three','journey','parallel'].includes(activeSmartTool)){box.innerHTML=emptyCard('Add recipes first so Kitchen Magic has something to work with.','Add recipe','add-recipe');return}const filtered=smartFilteredRecipes();
    if(activeSmartTool==='roulette'){const pick=filtered.length?filtered[Math.floor(Math.random()*filtered.length)]:null;box.innerHTML=pick?`<div class="smart-card"><p class="eyebrow">Bento picked</p><h3>${foodEmoji(pick)} ${esc(pick.title)}</h3><p class="muted">${totalTime(pick)} min · ${pick.energy} effort · cleanup ${pick.cleanup}/3</p><div class="action-row" style="margin-top:12px"><button class="primary-btn" data-recipe-id="${pick.id}">Open recipe</button><button class="soft-btn" data-plan-next="${pick.id}">Plan next</button><button class="soft-btn" data-smart-reroll>Roll again 🎲</button></div></div>`:smartRecipeResult('Bento Roulette',[]);return}
    if(activeSmartTool==='lazy'){const list=filtered.filter(r=>r.energy==='low'||Number(r.cleanup||2)===1||totalTime(r)<=20).sort((a,b)=>Number(a.cleanup)-Number(b.cleanup)||totalTime(a)-totalTime(b));box.innerHTML=smartRecipeResult('Low-effort picks',list,'Add energy/cleanup details to recipes to make this smarter.');return}
    if(activeSmartTool==='rescue'){const exp=expiringIngredientNames(),ctx=createMatchContext();const list=filtered.map(r=>({r,m:recipeMatch(r,[],ctx)})).filter(x=>x.m.useSoon>0).sort((a,b)=>b.m.useSoon-a.m.useSoon||b.m.percent-a.m.percent);box.innerHTML=`<div class="smart-card"><h3>🧊 Fridge Rescue</h3><p class="muted">Use soon: ${esc(exp.join(', ')||'Nothing is expiring soon.')}</p>${list.length?list.slice(0,8).map(x=>`<div class="list-card"><button class="content" data-recipe-id="${x.r.id}"><b>${foodEmoji(x.r)} ${esc(x.r.title)}</b><small>Uses ${x.m.useSoon} expiring item${x.m.useSoon>1?'s':''} · ${x.m.percent}% pantry match</small></button><button class="meta" data-plan-next="${x.r.id}">Plan</button></div>`).join(''):'<p class="muted" style="margin-top:10px">No saved recipe currently uses the expiring ingredients.</p>'}${list.length?'<button class="primary-btn full-btn" data-plan-expiry style="margin-top:10px">Plan best rescue meal</button>':''}</div>`;return}
    if(activeSmartTool==='complete'){box.innerHTML=`<div class="smart-card"><h3>🥗 Complete My Meal</h3><p class="muted">Choose your main and Bento will suggest complementary saved recipes.</p><div class="input-prompt"><select id="completeRecipeSelect">${recipeOptions()}</select><button data-complete-meal>Complete</button></div><div id="completeMealOutput"></div></div>`;return}
    if(activeSmartTool==='deadline'){box.innerHTML=`<div class="smart-card"><h3>⏰ Dinner Deadline</h3><p class="muted">Tell Bento when food should be ready and it will work backward.</p><div class="input-prompt"><select id="deadlineRecipeSelect">${recipeOptions()}</select><input id="deadlineTime" type="time" value="${esc(state.settings.defaultDinnerTime||'19:00')}"><button data-deadline-build>Plan</button></div><div id="deadlineOutput"></div></div>`;return}
    if(activeSmartTool==='parallel'){box.innerHTML=`<div class="smart-card"><h3>🕰️ Parallel Cooking Timeline</h3><p class="muted">Coordinate all saved recipes on one day so they finish together.</p><div class="input-prompt"><input id="parallelDate" type="date" value="${dateKey(new Date())}"><input id="parallelTime" type="time" value="${esc(state.settings.defaultDinnerTime||'19:00')}"><button data-parallel-build>Build timeline</button></div><div id="parallelOutput"></div></div>`;return}
    if(activeSmartTool==='prep'){const today=state.mealPlan[dateKey(new Date())]||{},recipes=MEAL_SLOTS.map(s=>getRecipe(today[s]?.recipeId)).filter(Boolean),notes=MEAL_SLOTS.map(s=>today[s]?.prepNote).filter(Boolean),all=[...new Set(recipes.flatMap(r=>(r.ingredients||[]).map(ingredientName)).filter(Boolean))];box.innerHTML=`<div class="smart-card"><h3>🔪 Mise en Place</h3>${recipes.length?`<p class="muted">For today's ${recipes.length} saved recipe${recipes.length>1?'s':''}.</p><div class="detail-section"><h3>Prep ingredients</h3>${all.slice(0,30).map(x=>`<div class="ingredient-line">○ ${esc(x)}</div>`).join('')}</div>${notes.length?`<div class="detail-section"><h3>Prep notes</h3>${notes.map(n=>`<div class="ingredient-line">○ ${esc(n)}</div>`).join('')}</div>`:''}`:'<p class="muted">Plan at least one saved recipe today to create a prep list.</p>'}<div class="detail-section"><h3>Tomorrow prep</h3>${tomorrowPrepItems().length?tomorrowPrepItems().map(x=>`<div class="ingredient-line">○ ${esc(x.title)} <small class="muted">· ${esc(x.sub)}</small></div>`).join(''):'<p class="muted">Nothing needs advance prep tomorrow.</p>'}</div></div>`;return}
    if(activeSmartTool==='batch'){const recipes=[];weekDates().forEach(d=>Object.values(state.mealPlan[dateKey(d)]||{}).forEach(i=>{const r=getRecipe(i?.recipeId);if(r)recipes.push(r)}));const map=new Map();recipes.forEach(r=>(r.ingredients||[]).forEach(line=>{const n=ingredientName(line);if(!n)return;const o=map.get(n)||{count:0,recipes:new Set()};o.count++;o.recipes.add(r.title);map.set(n,o)}));const overlaps=[...map.entries()].filter(([,v])=>v.recipes.size>=2).sort((a,b)=>b[1].recipes.size-a[1].recipes.size);box.innerHTML=`<div class="smart-card"><h3>🥘 Batch Prep</h3>${overlaps.length?`<p class="muted">Prep these once and use them across multiple meals this week.</p>${overlaps.slice(0,20).map(([name,v])=>`<div class="list-card"><span class="emoji">🔪</span><span class="content"><b>${esc(name)}</b><small>${esc([...v.recipes].join(' · '))}</small></span><span class="meta">×${v.recipes.size}</span></div>`).join('')}`:'<p class="muted">Plan more than one recipe this week to find overlapping prep.</p>'}</div>`;return}
    if(activeSmartTool==='three'){box.innerHTML=`<div class="smart-card"><h3>🧩 3-Ingredient Challenge</h3><p class="muted">Enter up to three ingredients. Bento ranks recipes by how many they use.</p><div class="input-prompt"><input id="threeIngredientsInput" placeholder="eggs, rice, carrots"><button data-three-match>Find</button></div><div id="threeOutput"></div></div>`;return}
    if(activeSmartTool==='journey'){const names=[...new Set(state.pantry.map(p=>p.name))].sort();box.innerHTML=`<div class="smart-card"><h3>🥕 Ingredient Journey</h3><p class="muted">See where an ingredient appears in this week’s plan and in your saved recipe library.</p><div class="input-prompt"><input id="journeyIngredientInput" list="journeyIngredients" placeholder="e.g. carrots"><datalist id="journeyIngredients">${names.slice(0,300).map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist><button data-journey-find>Trace</button></div><div id="journeyOutput"></div></div>`;return}
  }

  function renderBentoBuilder(){const options=recipeOptions();for(const id of ['bentoMain','bentoSide1','bentoSide2','bentoTreat']){const e=$(`#${id}`);if(e){const value=e.value;e.innerHTML=options;if(value)e.value=value}}renderBentoBalance();$('#savedBentos').innerHTML=state.bentos.length?[...state.bentos].reverse().map(b=>{const ids=[b.main,b.side1,b.side2,b.treat].filter(Boolean),rs=ids.map(getRecipe).filter(Boolean);return `<div class="smart-card"><div class="match-card-head"><div><b>🍱 ${esc(b.name||'Saved Bento')}</b><small class="muted">${esc(rs.map(r=>r.title).join(' · ')||'Empty bento')}</small></div></div><div class="action-row" style="margin-top:10px;margin-bottom:0"><button class="soft-btn" data-bento-grocery="${b.id}">Add groceries</button><button class="danger-btn" data-bento-delete="${b.id}">Delete</button></div></div>`}).join(''):emptyCard('Build your first lunchbox combination above.')}
  function renderBentoBalance(){const ids=['bentoMain','bentoSide1','bentoSide2','bentoTreat'].map(id=>$(`#${id}`)?.value).filter(Boolean),rs=ids.map(getRecipe).filter(Boolean),cats=rs.map(r=>(r.category||'').toLowerCase()),tags=[];tags.push(`<span class="balance-dot ${rs.length>=3?'good':''}">${rs.length}/4 compartments</span>`);tags.push(`<span class="balance-dot ${cats.some(c=>/side|salad|soup/.test(c))?'good':''}">🥬 side</span>`);tags.push(`<span class="balance-dot ${cats.some(c=>/dessert|snack/.test(c))?'good':''}">🍓 treat</span>`);tags.push(`<span class="balance-dot ${rs.some(r=>r.freezer==='yes')?'good':''}">❄ pack-ahead</span>`);$('#bentoBalance').innerHTML=tags.join('')}

  function leftoverRemix(l){const s=l.name.toLowerCase();if(/rice/.test(s))return'fried rice, rice balls or soup';if(/chicken/.test(s))return'sandwich, fried rice or noodle bowl';if(/beef|pork/.test(s))return'wrap, rice bowl or noodles';if(/veget/.test(s))return'omelet, soup or pasta';if(/curry/.test(s))return'curry udon or baked rice';return'wrap, rice bowl, soup or lunchbox side'}
  function renderLeftovers(){const list=[...state.leftovers].sort((a,b)=>daysUntil(a.useBy)-daysUntil(b.useBy));const soon=list.filter(l=>{const d=daysUntil(l.useBy);return d>=0&&d<=2}).length,total=list.reduce((n,l)=>n+Number(l.portions||0),0);$('#leftoverSummary').innerHTML=`<div class="stat-card"><strong>${list.length}</strong><small>containers</small></div><div class="stat-card"><strong>${total}</strong><small>portions</small></div><div class="stat-card"><strong>${soon}</strong><small>use soon</small></div>`;$('#leftoversList').innerHTML=list.length?list.map(l=>{const d=daysUntil(l.useBy),status=Number.isFinite(d)?(d<0?'expired':d===0?'use today':`${d}d left`):'no date';return `<div class="smart-card"><div class="match-card-head"><div><b>♻️ ${esc(l.name)}</b><small class="muted">${l.portions} portion${l.portions==1?'':'s'} · ${esc(l.location||'Fridge')} · ${esc(status)}</small></div></div><p class="muted" style="margin-top:7px">Remix: ${esc(leftoverRemix(l))}</p><div class="action-row" style="margin-top:10px;margin-bottom:0"><button class="soft-btn" data-leftover-plan="${l.id}">Plan tomorrow lunch</button><button class="soft-btn" data-leftover-use="${l.id}">Use 1 portion</button><button class="danger-btn" data-leftover-delete="${l.id}">Delete</button></div></div>`}).join(''):emptyCard('No leftovers saved. Planned extras can land here after cooking.','Add leftover','add-leftover')}

  function renderIdeas(){const list=[...state.ideas].sort((a,b)=>Number(!!a.done)-Number(!!b.done)||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));$('#ideasList').innerHTML=list.length?list.map(i=>`<article class="idea-card"><div class="idea-card-head"><div><h3>${i.done?'✓ ':''}${esc(i.title)}</h3><span class="tag-pill">${esc(i.type||'Idea')}</span>${i.date?`<span class="tag-pill">${esc(i.date)}</span>`:''}</div><button class="icon-btn" data-idea-done="${i.id}" aria-label="${i.done?'Mark active':'Mark done'}">${i.done?'↺':'✓'}</button></div>${i.notes?`<p class="muted">${esc(i.notes)}</p>`:''}<div class="subtle-action-row"><button class="soft-btn" data-idea-recipe="${i.id}">Turn into recipe</button><button class="danger-btn" data-idea-delete="${i.id}">Delete</button></div></article>`).join(''):emptyCard('No ideas yet. Add a craving or something you want to try when inspiration hits.','Add idea','add-idea')}

  function templateMealCount(t){return (t.days||[]).reduce((n,d)=>n+Object.keys(d||{}).length,0)}
  function saveVisibleWeekTemplate(){const name=$('#templateNameInput')?.value.trim(),days=weekDates().map(d=>JSON.parse(JSON.stringify(state.mealPlan[dateKey(d)]||{}))),count=days.reduce((n,d)=>n+Object.keys(d).length,0);if(!count){toast('There are no meals in this visible week to save');return}if(!name){toast('Give the template a name');$('#templateNameInput')?.focus();return}state.templates.push({id:uid('template'),name:name.slice(0,60),days,createdAt:new Date().toISOString()});$('#templateNameInput').value='';commit();toast('Meal template saved')}
  function applyTemplate(id){const t=state.templates.find(x=>x.id===id);if(!t)return;const dates=weekDates(),addedRefs=[];let added=0;dates.forEach((d,i)=>{const key=dateKey(d),source=t.days?.[i]||{};state.mealPlan[key]||={};for(const slot of MEAL_SLOTS){if(!state.mealPlan[key][slot]&&source[slot]){const item=cloneData(source[slot]);if(item.recipeId&&!getRecipe(item.recipeId))continue;state.mealPlan[key][slot]=item;addedRefs.push([key,slot]);added++}}if(!Object.keys(state.mealPlan[key]).length)delete state.mealPlan[key]});commit();toast(added?`Filled ${added} empty meal slot${added===1?'':'s'}`:'This week has no empty matching slots',added?()=>{for(const [key,slot] of addedRefs){if(state.mealPlan[key]){delete state.mealPlan[key][slot];if(!Object.keys(state.mealPlan[key]).length)delete state.mealPlan[key]}}}:null)}

  function renderTemplates(){const list=[...state.templates].reverse();$('#templatesList').innerHTML=list.length?list.map(t=>`<article class="template-card"><div class="template-card-head"><div><h3>🗓️ ${esc(t.name)}</h3><small class="muted">${templateMealCount(t)} planned meal${templateMealCount(t)===1?'':'s'}</small></div></div><div class="template-days">${(t.days||[]).map((d,i)=>{const labels=state.settings.weekStart==='sunday'?['Sun','Mon','Tue','Wed','Thu','Fri','Sat']:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];return `<span>${labels[i]||`Day ${i+1}`} · ${Object.keys(d||{}).length}</span>`}).join('')}</div><div class="subtle-action-row"><button class="primary-btn" data-template-apply="${t.id}">Fill empty slots</button><button class="danger-btn" data-template-delete="${t.id}">Delete</button></div></article>`).join(''):emptyCard('No meal templates yet. Plan a week you like, then save it here for later.')}

  function renderWaste(){const list=[...state.wasteLog].sort((a,b)=>String(b.date||b.createdAt||'').localeCompare(String(a.date||a.createdAt||''))),monthAgo=Date.now()-30*86400000,recent=list.filter(w=>new Date(w.date||w.createdAt).getTime()>=monthAgo),reasons=new Map();for(const w of recent)reasons.set(w.reason,(reasons.get(w.reason)||0)+1);const top=[...reasons.entries()].sort((a,b)=>b[1]-a[1])[0];$('#wasteSummary').innerHTML=`<div class="stat-card"><strong>${list.length}</strong><small>total logs</small></div><div class="stat-card"><strong>${recent.length}</strong><small>last 30 days</small></div><div class="stat-card"><strong>${esc(top?.[0]||'—')}</strong><small>top reason</small></div>`;$('#wasteList').innerHTML=list.length?list.map(w=>`<article class="waste-card"><div class="waste-card-head"><div><h3>🌱 ${esc(w.item)}</h3><span class="tag-pill">${esc(w.reason||'Other')}</span>${w.amount?`<span class="tag-pill">${esc(w.amount)}</span>`:''}</div><button class="danger-btn" data-waste-delete="${w.id}">Delete</button></div><p class="muted">${esc(w.date||'No date')}${w.note?` · ${esc(w.note)}`:''}</p></article>`).join(''):emptyCard('Nothing logged — which is perfectly fine. This tracker is optional.','Log waste','add-waste')}

  function renderCollections(){const cooked=cookCountMap(),custom=[...new Set(state.recipes.map(r=>r.collection).filter(Boolean))].sort();const cards=[['♡','Favorites',state.recipes.filter(r=>r.favorite).length,'Favorites'],['⚡','Quick Meals',state.recipes.filter(r=>totalTime(r)<=30).length,'Quick'],['🧼','Low Cleanup',state.recipes.filter(r=>Number(r.cleanup||2)<=1).length,'Low Cleanup'],['❄️','Freezer Friendly',state.recipes.filter(r=>r.freezer==='yes').length,'Freezer Friendly'],['🌱','Never Cooked',state.recipes.filter(r=>(cooked.get(r.id)||0)===0).length,'NeverCooked'],...custom.map(c=>['📚',c,state.recipes.filter(r=>r.collection===c).length,`Collection:${c}`])];$('#collectionsGrid').innerHTML=cards.map(([icon,name,count,filter])=>`<button class="collection-card" data-collection-filter="${esc(filter)}"><span>${icon}</span><b>${esc(name)}</b><small>${count} recipe${count===1?'':'s'}</small></button>`).join('')}

  function renderInsights(){const now=Date.now(),weekAgo=now-7*86400000,monthAgo=now-30*86400000,cookedWeek=state.history.filter(h=>new Date(h.date).getTime()>=weekAgo).length,unique=new Set(state.history.filter(h=>new Date(h.date).getTime()>=monthAgo).map(h=>h.recipeId)).size;$('#insightStats').innerHTML=`<div class="stat-card"><strong>${cookedWeek}</strong><small>cooked this week</small></div><div class="stat-card"><strong>${unique}</strong><small>different recipes</small></div><div class="stat-card"><strong>${state.stats.rescuedCount||0}</strong><small>food rescues</small></div>`;const g=state.goals;const goalCard=(label,value,goal)=>{const pct=goal?Math.min(100,Math.round(value/goal*100)):0;return `<div class="smart-card"><div class="match-card-head"><b>${label}</b><strong>${goal?`${value}/${goal}`:'Not set'}</strong></div><div class="goal-progress"><i style="width:${pct}%"></i></div></div>`};$('#goalCards').innerHTML=goalCard('Home-cooked meals',cookedWeek,g.cookPerWeek)+goalCard('Different recipes this month',unique,g.newPerMonth)+goalCard('Pantry rescues',state.stats.rescuedCount||0,g.rescuePerMonth);const counts=cookCountMap(),ranked=state.recipes.map(r=>({r,n:counts.get(r.id)||0})).sort((a,b)=>b.n-a.n),top=ranked.filter(x=>x.n>0).slice(0,3),never=ranked.filter(x=>x.n===0).slice(0,3),recentWaste=state.wasteLog.filter(w=>new Date(w.date||w.createdAt).getTime()>=monthAgo),reasons=new Map();recentWaste.forEach(w=>reasons.set(w.reason,(reasons.get(w.reason)||0)+1));const wasteTop=[...reasons.entries()].sort((a,b)=>b[1]-a[1])[0];$('#rotationInsights').innerHTML=`<div class="smart-card"><h3>🏆 Regular rotation</h3>${top.length?top.map(x=>`<button class="list-card" data-recipe-id="${x.r.id}"><span class="emoji">${foodEmoji(x.r)}</span><span class="content"><b>${esc(x.r.title)}</b><small>Cooked ${x.n} time${x.n===1?'':'s'}</small></span><span class="meta">›</span></button>`).join(''):'<p class="muted">Cook a few recipes and Bento will learn your regular rotation.</p>'}</div><div class="smart-card"><h3>🌱 Try something new</h3>${never.length?never.map(x=>`<button class="list-card" data-recipe-id="${x.r.id}"><span class="emoji">${foodEmoji(x.r)}</span><span class="content"><b>${esc(x.r.title)}</b><small>Saved but never cooked</small></span><span class="meta">›</span></button>`).join(''):'<p class="muted">You have tried every saved recipe.</p>'}</div><div class="smart-card"><h3>♻️ Waste pattern</h3><p class="muted">${recentWaste.length?`${recentWaste.length} log${recentWaste.length===1?'':'s'} in the last 30 days${wasteTop?` · most often: ${esc(wasteTop[0])}`:''}.`:'No waste logs in the last 30 days. Tracking is optional.'}</p>${recentWaste.length?'<button class="soft-btn" data-view-link="waste" style="margin-top:10px">Open waste log</button>':''}</div>`}

  function renderHistory(){const list=[...state.history].sort((a,b)=>String(b.date).localeCompare(String(a.date))),visible=list.slice(0,historyRenderLimit);$('#historyList').innerHTML=list.length?visible.map(h=>{const r=getRecipe(h.recipeId);return `<div class="list-card"><button class="content" ${r?`data-recipe-id="${r.id}"`:''}><b>${foodEmoji(r)} ${esc(r?.title||h.title||'Recipe')}</b><small>${esc(formatDateTime(h.date))}</small></button><button class="meta" data-history-rate="${h.id}" aria-label="Rate">${h.rating?`${'★'.repeat(h.rating)}`:'Rate ☆'}</button></div>`}).join('')+(list.length>visible.length?`<div class="load-more-wrap"><button class="soft-btn load-more-btn" data-load-more-history>Show more · ${list.length-visible.length} remaining</button></div>`:''):emptyCard('When you finish cooking a recipe, it will be remembered here.')}
  function renderSettings(){applyTheme();$('#displayNameInput').value=state.settings.displayName||'';$('#servingsInput').value=state.settings.defaultServings??2;$('#unitsSelect').value=state.settings.units||'metric';$('#weekStartSelect').value=state.settings.weekStart||'monday';$('#dietInput').value=state.settings.diet||'';$('#allergyInput').value=state.settings.allergies||'';$('#equipmentInput').value=state.settings.equipment||'';$('#weeklyGoalInput').value=state.settings.weeklyGoal??0;$('#expiryWindowSelect').value=String(state.settings.expiryWarningDays||3);$('#defaultPantryLocationSelect').value=state.settings.defaultPantryLocation||'Pantry';$('#currencySelect').value=state.settings.currency||'PHP';$('#densitySelect').value=state.settings.density||'cozy';$('#defaultDinnerTimeInput').value=state.settings.defaultDinnerTime||'19:00';$('#defaultLeftoverDaysSelect').value=String(state.settings.defaultLeftoverDays||3);$('#slotBreakfastInput').checked=state.settings.mealSlots?.breakfast!==false;$('#slotLunchInput').checked=state.settings.mealSlots?.lunch!==false;$('#slotDinnerInput').checked=state.settings.mealSlots?.dinner!==false;$('#slotSnackInput').checked=state.settings.mealSlots?.snack!==false;$('#showHomeStatsInput').checked=state.settings.showHomeStats!==false;$('#showHomeFavoritesInput').checked=state.settings.showHomeFavorites!==false;$('#showTomorrowPrepInput').checked=state.settings.showTomorrowPrep!==false;$('#showHomeQuickActionsInput').checked=state.settings.showHomeQuickActions!==false;$('#autoStapleGroceriesInput').checked=state.settings.autoStapleGroceries!==false;$('#askPantryDeductInput').checked=state.settings.askPantryDeductAfterCook!==false;$('#themePicker').innerHTML=Object.entries(THEMES).map(([k,t])=>`<button class="theme-swatch ${state.settings.theme===k?'active':''}" data-theme="${k}" style="background:linear-gradient(135deg,${t.soft},${t.accent})"><span>${t.label}</span></button>`).join('')}

  function renderCurrentView(){applyTheme();const map={home:renderHome,plan:renderPlan,recipes:renderRecipes,pantry:renderPantry,grocery:renderGrocery,cookwith:renderCookMatches,smart:renderSmart,bentobox:renderBentoBuilder,leftovers:renderLeftovers,collections:renderCollections,insights:renderInsights,favorites:renderRecipes,history:renderHistory,activity:renderActivity,settings:renderSettings,ideas:renderIdeas,templates:renderTemplates,waste:renderWaste};(map[currentView]||(()=>{}))()}

  function openDialog(d){if(d&&!d.open)d.showModal()}
  function openRecipeForm(r=null){$('#recipeForm').reset();$('#recipeId').value=r?.id||'';$('#recipeDialogTitle').textContent=r?'Edit Recipe':'Add Recipe';$('#recipeTitleInput').value=r?.title||'';$('#recipeCategoryInput').value=r?.category||'Dinner';$('#recipeCuisineInput').value=r?.cuisine||'';$('#recipePrepInput').value=r?.prep??0;$('#recipeCookInput').value=r?.cook??0;$('#recipeServingsInput').value=r?.servings||state.settings.defaultServings||2;$('#recipeEnergyInput').value=r?.energy||'normal';$('#recipeCleanupInput').value=String(r?.cleanup||2);$('#recipeFreezerInput').value=r?.freezer||'no';$('#recipeEquipmentInput').value=r?.equipment||'';$('#recipeIngredientsInput').value=(r?.ingredients||[]).join('\n');$('#recipeStepsInput').value=(r?.steps||[]).join('\n');$('#recipeNotesInput').value=r?.notes||'';$('#recipeCollectionInput').value=r?.collection||'';$('#recipeSourceInput').value=r?.source||'';openDialog($('#recipeDialog'));setTimeout(()=>$('#recipeTitleInput').focus(),80)}
  function openPantryForm(p=null){$('#pantryForm').reset();$('#pantryId').value=p?.id||'';$('#pantryDialogTitle').textContent=p?'Edit Pantry Item':'Add Pantry Item';$('#pantryNameInput').value=p?.name||'';$('#pantryQtyInput').value=p?.quantity??1;$('#pantryUnitInput').value=p?.unit||'';$('#pantryLocationInput').value=p?.location||state.settings.defaultPantryLocation||'Pantry';$('#pantryExpiryInput').value=p?.expiry||'';$('#pantryOpenedInput').value=p?.opened||'';$('#pantryPackageInput').value=p?.packageSize||'';$('#pantryStoreInput').value=p?.store||'';$('#pantryThresholdInput').value=p?.lowThreshold??'';$('#pantryStapleInput').checked=!!p?.staple;$('#pantryLowInput').checked=!!p?.lowStock;$('#deletePantryButton').style.visibility=p?'visible':'hidden';openDialog($('#pantryDialog'));setTimeout(()=>$('#pantryNameInput').focus(),80)}

  function openMealForm(date,slot){const cur=state.mealPlan[date]?.[slot];$('#mealDateInput').value=date;$('#mealSlotInput').value=slot;$('#mealDialogDate').textContent=parseDate(date).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});$('#mealDialogTitle').textContent=slot[0].toUpperCase()+slot.slice(1);const selectedRecipeId=cur?.recipeId||pendingPlanRecipeId||'';$('#mealRecipeSelect').innerHTML=recipeOptions(selectedRecipeId);$('#mealCustomInput').value=cur?.custom||'';const r=getRecipe(selectedRecipeId);$('#mealServingsInput').value=cur?.servings||r?.servings||state.settings.defaultServings||2;$('#mealPrepNoteInput').value=cur?.prepNote||'';$('#mealExtraPortionsInput').value=cur?.extraPortions??(cur?.planLeftovers?1:0);$('#removeMealButton').style.visibility=cur?'visible':'hidden';$('#swapMealButton').disabled=state.recipes.length<1;openDialog($('#mealDialog'))}

  function openLeftoverForm(){ $('#leftoverForm').reset();$('#leftoverPortionsInput').value=1;const d=new Date();d.setDate(d.getDate()+3);$('#leftoverUseByInput').value=dateKey(d);openDialog($('#leftoverDialog')) }
  function openIdeaForm(){ $('#ideaForm').reset();openDialog($('#ideaDialog'));setTimeout(()=>$('#ideaTitleInput').focus(),80) }
  function openWasteForm(){ $('#wasteForm').reset();$('#wasteDateInput').value=dateKey(new Date());openDialog($('#wasteDialog'));setTimeout(()=>$('#wasteItemInput').focus(),80) }
  function openRecipeDetail(id){const r=getRecipe(id);if(!r)return;$('#recipeDetailContent').innerHTML=`<div class="sheet-handle"></div><div class="dialog-title"><div><p class="eyebrow">${esc(r.cuisine||'Recipe')}</p><h2>${esc(r.title)}</h2></div><button class="icon-btn close-dialog">×</button></div><div class="detail-hero"><div class="food-emoji">${foodEmoji(r)}</div><div class="detail-meta"><span class="badge">${totalTime(r)} min</span><span class="badge">${r.servings||2} servings</span><span class="badge">${esc(r.category||'Other')}</span><span class="badge">${r.energy} effort</span><span class="badge">cleanup ${r.cleanup}/3</span>${r.freezer==='yes'?'<span class="badge">❄ freezer friendly</span>':''}${r.collection?`<span class="badge">${esc(r.collection)}</span>`:''}</div></div><div class="detail-section"><h3>Ingredients</h3>${(r.ingredients||[]).length?r.ingredients.map(i=>`<div class="ingredient-line">○ ${esc(i)}</div>`).join(''):'<span class="muted">No ingredients added.</span>'}</div><div class="detail-section"><h3>Steps</h3>${(r.steps||[]).length?r.steps.map((s,i)=>`<div class="step-line"><b>${i+1}.</b> ${esc(s)}</div>`).join(''):'<span class="muted">No steps added.</span>'}</div>${r.notes?`<div class="detail-section"><h3>Next-time notes</h3><p>${esc(r.notes)}</p></div>`:''}${r.equipment?`<div class="detail-section"><h3>Equipment</h3><p>${esc(r.equipment)}</p></div>`:''}${r.source?`<div class="detail-section"><h3>Source</h3><p>${esc(r.source)}</p></div>`:''}<div class="detail-actions"><button class="soft-btn" data-detail-fav="${r.id}">${r.favorite?'♥ Favorited':'♡ Favorite'}</button><button class="soft-btn" data-detail-edit="${r.id}">Edit</button><button class="soft-btn" data-detail-grocery="${r.id}">Add ingredients</button><button class="soft-btn" data-detail-plan="${r.id}">Plan this</button><button class="primary-btn" data-start-cook="${r.id}">Start cooking</button><button class="danger-btn" data-detail-delete="${r.id}">Delete recipe</button></div>`;openDialog($('#recipeDetailDialog'))}

  async function requestWakeLock(){try{if('wakeLock'in navigator&&!wakeLock)wakeLock=await navigator.wakeLock.request('screen')}catch{}}
  async function releaseWakeLock(){try{await wakeLock?.release()}catch{}wakeLock=null}
  function formatTimer(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
  function startCooking(id){const r=getRecipe(id);if(!r)return;cookingSession={recipeId:id,step:0,checked:new Set()};timerSeconds=0;timerEndAt=0;stopCookingTimer(false);requestWakeLock();renderCookingMode()}
  function renderCookingMode(){const r=getRecipe(cookingSession?.recipeId);if(!r)return;const steps=(r.steps||[]).length?r.steps:['Enjoy making your recipe!'],i=clamp(cookingSession.step,0,steps.length-1);cookingSession.step=i;$('#recipeDetailContent').innerHTML=`<div class="cook-mode"><div class="sheet-handle"></div><div class="dialog-title"><div><p class="eyebrow">Cooking mode · ${i+1}/${steps.length}</p><h2>${esc(r.title)}</h2></div><button class="icon-btn close-dialog">×</button></div><div class="cook-progress"><i style="width:${((i+1)/steps.length)*100}%"></i></div><div class="cook-step">${esc(steps[i])}</div><div class="cook-ingredients">${(r.ingredients||[]).slice(0,16).map((ing,idx)=>`<label class="cook-ingredient"><input type="checkbox" data-cook-ing="${idx}" ${cookingSession.checked.has(idx)?'checked':''}><span>${esc(ing)}</span></label>`).join('')}</div><div class="timer-box"><strong id="timerDisplay">${formatTimer(timerSeconds)}</strong><div class="action-row" style="justify-content:center;margin-top:8px"><button class="soft-btn" data-timer-add="60">+1 min</button><button class="soft-btn" data-timer-add="300">+5 min</button><button class="soft-btn" data-timer-toggle>${cookingTimer?'Pause':'Start timer'}</button><button class="soft-btn" data-timer-reset>Reset</button></div></div><div class="detail-actions"><button class="soft-btn" data-cook-prev ${i===0?'disabled':''}>‹ Previous</button><button class="soft-btn" data-cook-next>${i===steps.length-1?'Stay here':'Next ›'}</button><button class="primary-btn" data-cook-finish>Finish cooking</button></div></div>`}
  function syncCookingTimer(){if(!cookingTimer||!timerEndAt)return;timerSeconds=Math.max(0,Math.ceil((timerEndAt-Date.now())/1000));const d=$('#timerDisplay');if(d)d.textContent=formatTimer(timerSeconds);if(timerSeconds<=0){clearInterval(cookingTimer);cookingTimer=null;timerEndAt=0;toast('Timer finished ✿');navigator.vibrate?.([120,80,120]);if(cookingSession)renderCookingMode()}}
  function startCookingTimer(){if(cookingTimer)return;if(timerSeconds<=0)timerSeconds=60;timerEndAt=Date.now()+timerSeconds*1000;cookingTimer=setInterval(syncCookingTimer,500);renderCookingMode()}
  function stopCookingTimer(render=true){if(cookingTimer){syncCookingTimer();clearInterval(cookingTimer);cookingTimer=null}timerEndAt=0;if(render&&cookingSession)renderCookingMode()}
  function finishCooking(){const r=getRecipe(cookingSession?.recipeId);if(!r)return;state.history.push({id:uid('history'),recipeId:r.id,title:r.title,date:new Date().toISOString(),rating:0});const today=state.mealPlan[dateKey(new Date())]||{},planned=Object.values(today).find(i=>i?.recipeId===r.id&&Number(i.extraPortions)>0&&!i.leftoverSaved);let savedLeftover=null;if(planned){const d=new Date();d.setDate(d.getDate()+state.settings.defaultLeftoverDays);savedLeftover={id:uid('left'),name:r.title,portions:Number(planned.extraPortions)||1,useBy:dateKey(d),location:'Fridge',notes:'Planned extra portion',createdAt:new Date().toISOString()};state.leftovers.push(savedLeftover);planned.leftoverSaved=true}const expiring=expiringIngredientNames();if((r.ingredients||[]).some(i=>expiring.some(p=>ingredientMatches(i,p))))state.stats.rescuedCount=(state.stats.rescuedCount||0)+1;commit(false);cookingSession=null;stopCookingTimer(false);releaseWakeLock();$('#recipeDetailDialog').close();const shouldReview=state.settings.askPantryDeductAfterCook!==false&&openPantryDeductionReview(r);toast(savedLeftover?`Cooked — ${savedLeftover.portions} leftover portion${savedLeftover.portions===1?'':'s'} saved ♡`:'Saved to cooking history ♡');if(!shouldReview&&currentView==='history')renderHistory()}

  function addRecipeIngredientsToGrocery(r,missingOnly=false){const pantry=state.pantry.map(p=>p.name);let lines=r.ingredients||[];if(missingOnly)lines=lines.filter(i=>!pantry.some(p=>ingredientMatches(i,p)));const addedIds=[];for(const line of lines){const name=ingredientName(line)||line.trim();if(!name)continue;const ex=state.grocery.find(g=>ingredientMatches(g.ingredientName||g.text,name)&&!g.checked);if(!ex){const g={id:uid('g'),text:line.trim(),ingredientName:name,checked:false,category:groceryCategory(line),source:`recipe:${r.id}`};state.grocery.push(g);addedIds.push(g.id)}}commit();toast(addedIds.length?`${addedIds.length} item${addedIds.length===1?'':'s'} added to groceries`:'Everything is already listed',addedIds.length?()=>{state.grocery=state.grocery.filter(g=>!addedIds.includes(g.id))}:null)}

  function generateGroceriesFromWeek(){const reqs=aggregateWeekRequirements();if(!reqs.length){toast('Plan at least one saved recipe this week first');return}const addedIds=[];for(const req of reqs){const built=buildGroceryFromRequirement(req);if(!built)continue;if(state.grocery.some(g=>!g.checked&&ingredientMatches(g.ingredientName||g.text,req.name)))continue;const g={id:uid('g'),checked:false,...built};state.grocery.push(g);addedIds.push(g.id)}const stapleBefore=new Set(state.grocery.map(g=>g.id));ensureRecurringStaples(false);const stapleAdded=state.grocery.filter(g=>!stapleBefore.has(g.id)).map(g=>g.id);addedIds.push(...stapleAdded);commit();toast(addedIds.length?`${addedIds.length} grocery item${addedIds.length===1?'':'s'} added with pantry/package checks`:'Your current pantry/list already covers the plan',addedIds.length?()=>{state.grocery=state.grocery.filter(g=>!addedIds.includes(g.id))}:null)}

  function lowStockToGrocery(){const ids=[];for(const p of state.pantry.filter(x=>x.lowStock)){if(!state.grocery.some(g=>!g.checked&&ingredientMatches(g.ingredientName||g.text,p.name))){const g={id:uid('g'),text:p.name,ingredientName:p.name,checked:false,category:groceryCategory(p.name),source:p.staple?'recurring-staple':'low-stock'};state.grocery.push(g);ids.push(g.id)}}commit();toast(ids.length?`${ids.length} low-stock item${ids.length===1?'':'s'} added`:'Low-stock items are already listed',ids.length?()=>{state.grocery=state.grocery.filter(g=>!ids.includes(g.id))}:null)}

  function checkedToPantry(){const checked=state.grocery.filter(g=>g.checked);if(!checked.length){toast('Check purchased items first');return}const changes=[],addedIds=[],purchaseIds=[];for(const g of checked){const name=g.ingredientName||ingredientName(g.text)||g.text,existing=state.pantry.find(p=>ingredientMatches(p.name,name));let addQty=Number(g.purchaseQty),addUnit=g.purchaseUnit||'',displayUnit=g.purchaseDisplayUnit||addUnit;if(!Number.isFinite(addQty)){addQty=1;addUnit='';displayUnit=''}if(existing){changes.push({id:existing.id,before:cloneData(existing)});const existingBase=toBaseQty(existing.quantity,existing.unit);if(existingBase&&addUnit&&existingBase.baseUnit===addUnit)existing.quantity=Number(existing.quantity||0)+fromBaseQty(addQty,existing.unit);else existing.quantity=Number(existing.quantity||0)+1;existing.lowStock=false;existing.updatedAt=new Date().toISOString();updateLowStockState(existing)}else{const unit=addUnit==='count'?'':displayUnit,qty=unit&&unitDef(unit)?.[0]===addUnit?fromBaseQty(addQty,unit):addQty,p={id:uid('pantry'),name:name[0]?.toUpperCase()+name.slice(1),quantity:qty,unit,location:state.settings.defaultPantryLocation||'Pantry',expiry:'',opened:'',packageSize:'',store:'',staple:false,lowStock:false,lowThreshold:null,updatedAt:new Date().toISOString()};state.pantry.push(p);addedIds.push(p.id)}const histUnit=addUnit==='count'?'':displayUnit,histAmount=histUnit&&unitDef(histUnit)?.[0]===addUnit?fromBaseQty(addQty,histUnit):addQty;const h={id:uid('purchase'),item:name,amount:histAmount,unit:histUnit,date:new Date().toISOString(),grocery:cloneData(g)};state.purchaseHistory.push(h);if(state.purchaseHistory.length>5000)state.purchaseHistory.splice(0,state.purchaseHistory.length-5000);purchaseIds.push(h.id)}const removed=checked.map(cloneData);state.grocery=state.grocery.filter(g=>!g.checked);ensureRecurringStaples(false);commit();const undo=()=>{for(const c of changes){const p=state.pantry.find(x=>x.id===c.id);if(p)Object.assign(p,c.before)}state.pantry=state.pantry.filter(p=>!addedIds.includes(p.id));state.grocery.push(...removed);state.purchaseHistory=state.purchaseHistory.filter(h=>!purchaseIds.includes(h.id))};toast(`${checked.length} purchased item${checked.length===1?'':'s'} moved to pantry`,undo)}


  async function shareGroceries(){const items=state.grocery.filter(g=>!g.checked);if(!items.length){toast('Nothing unchecked to share');return}const text=['Bento Grocery List',...items.map(g=>`☐ ${g.text}`)].join('\n');try{if(navigator.share)await navigator.share({title:'Bento Grocery List',text});else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);toast('Grocery list copied')}else toast('Sharing is not available on this device')}catch(err){if(err?.name!=='AbortError')toast('Could not share the grocery list')}}

  function exportBackup(){persistNow();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`bento-backup-${dateKey(new Date())}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast('Backup exported')}
  async function importBackup(file){if(!file)return;try{const raw=JSON.parse(await file.text());state=normalizeState(raw);persistNow();renderCurrentView();renderGlobalBadges();toast('Backup restored')}catch{toast('That backup could not be read')}}

  function copyWeek(){const from=weekDates(),to=weekDates(weekOffset+1),before=new Map();let count=0;from.forEach((d,i)=>{const src=state.mealPlan[dateKey(d)],key=dateKey(to[i]);before.set(key,cloneData(state.mealPlan[key]||null));if(src){state.mealPlan[key]=cloneData(src);count+=Object.keys(src).length}});commit();toast(count?`Copied ${count} meal${count===1?'':'s'} to next week`:'Nothing planned to copy',count?()=>{for(const [key,val] of before){if(val)state.mealPlan[key]=val;else delete state.mealPlan[key]}}:null)}

  function clearWeek(){if(!confirm('Clear all meals from this visible week?'))return;const before=new Map();weekDates().forEach(d=>{const k=dateKey(d);before.set(k,cloneData(state.mealPlan[k]||null));delete state.mealPlan[k]});commit();toast('Week cleared',()=>{for(const [k,v] of before)if(v)state.mealPlan[k]=v})}

