  $('#clearActivityButton').addEventListener('click',()=>{if(!state.purchaseHistory.length&&!state.useHistory.length){toast('Activity is already empty');return}if(!confirm('Clear the local bought/used activity history?'))return;const p=cloneData(state.purchaseHistory),u=cloneData(state.useHistory);state.purchaseHistory=[];state.useHistory=[];commit();toast('Kitchen activity cleared',()=>{state.purchaseHistory=p;state.useHistory=u})});
  $('#prevWeek').addEventListener('click',()=>{weekOffset--;renderPlan()});$('#nextWeek').addEventListener('click',()=>{weekOffset++;renderPlan()});$('#copyWeekButton').addEventListener('click',copyWeek);$('#clearWeekButton').addEventListener('click',clearWeek);
  $('#generateGroceriesButton').addEventListener('click',()=>{generateGroceriesFromWeek();navigate('grocery')});$('#groceryFromPlanButton').addEventListener('click',generateGroceriesFromWeek);$('#addLowStockToGrocery').addEventListener('click',lowStockToGrocery);$('#checkedToPantryButton').addEventListener('click',checkedToPantry);
  $('#groceryAddButton').addEventListener('click',()=>{const input=$('#groceryAddInput'),text=input.value.trim();if(!text)return;state.grocery.push({id:uid('g'),text,checked:false,category:groceryCategory(text),source:'manual'});input.value='';commit()});$('#groceryAddInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#groceryAddButton').click()}});$('#clearCheckedButton').addEventListener('click',()=>{const removed=state.grocery.filter(g=>g.checked).map(cloneData);if(!removed.length){toast('No checked items to clear');return}state.grocery=state.grocery.filter(g=>!g.checked);commit();toast('Checked items cleared',()=>state.grocery.push(...removed))});$('#shareGroceryButton').addEventListener('click',shareGroceries);$('#shoppingModeButton').addEventListener('click',async()=>{document.body.classList.toggle('shopping-mode');if(document.body.classList.contains('shopping-mode')){await requestWakeLock();toast('Shopping mode on')}else await releaseWakeLock()});
  $('#matchRecipesButton').addEventListener('click',()=>{matchRenderLimit=MATCH_RENDER_BATCH;renderCookMatches()});$('#customCookIngredients').addEventListener('input',debounce(()=>{matchRenderLimit=MATCH_RENDER_BATCH;renderCookMatches()},90));$('#pantrySortButton').addEventListener('click',()=>{pantrySort=pantrySort==='expiry'?'name':'expiry';renderPantry()});$('#recipeSearch').addEventListener('input',debounce(()=>{recipeRenderLimit=RECIPE_RENDER_BATCH;renderRecipes()},100));$('#recipeSort').addEventListener('change',renderRecipes);$('#pantrySearch').addEventListener('input',debounce(()=>{pantryRenderLimit=PANTRY_RENDER_BATCH;renderPantry()},100));
  $('#newBentoButton').addEventListener('click',()=>{$('#bentoNameInput').value='';for(const id of ['bentoMain','bentoSide1','bentoSide2','bentoTreat'])$(`#${id}`).value='';renderBentoBalance()});$('#saveBentoButton').addEventListener('click',()=>{const b={id:uid('bento'),name:$('#bentoNameInput').value.trim()||'My Bento',main:$('#bentoMain').value,side1:$('#bentoSide1').value,side2:$('#bentoSide2').value,treat:$('#bentoTreat').value,createdAt:new Date().toISOString()};if(![b.main,b.side1,b.side2,b.treat].some(Boolean)){toast('Add at least one recipe to the bento');return}state.bentos.push(b);commit();toast('Bento combination saved 🍱')});
  $('#editGoalsButton').addEventListener('click',()=>{$('#goalCookInput').value=state.goals.cookPerWeek;$('#goalNewInput').value=state.goals.newPerMonth;$('#goalRescueInput').value=state.goals.rescuePerMonth;openDialog($('#goalDialog'))});
  $('#saveWeekTemplateButton').addEventListener('click',saveVisibleWeekTemplate);

  for(const [id,key,parser] of [['displayNameInput','displayName',v=>v.trim()],['servingsInput','defaultServings',v=>clamp(Number(v)||2,1,30)],['unitsSelect','units',v=>v],['weekStartSelect','weekStart',v=>v],['dietInput','diet',v=>v.trim()],['allergyInput','allergies',v=>v.trim()],['equipmentInput','equipment',v=>v.trim()],['weeklyGoalInput','weeklyGoal',v=>clamp(Number(v)||0,0,28)],['expiryWindowSelect','expiryWarningDays',v=>clamp(Number(v)||3,1,30)],['defaultPantryLocationSelect','defaultPantryLocation',v=>v],['currencySelect','currency',v=>v],['densitySelect','density',v=>v],['defaultDinnerTimeInput','defaultDinnerTime',v=>/^\d{2}:\d{2}$/.test(v)?v:'19:00'],['defaultLeftoverDaysSelect','defaultLeftoverDays',v=>clamp(Number(v)||3,1,14)]]){$(`#${id}`).addEventListener('change',e=>{state.settings[key]=parser(e.target.value);if(key==='weeklyGoal')state.goals.cookPerWeek=state.settings.weeklyGoal;commit();applyTheme()})}
  for(const [id,slot] of [['slotBreakfastInput','breakfast'],['slotLunchInput','lunch'],['slotDinnerInput','dinner'],['slotSnackInput','snack']]){$(`#${id}`).addEventListener('change',e=>{state.settings.mealSlots[slot]=e.target.checked;if(!Object.values(state.settings.mealSlots).some(Boolean)){state.settings.mealSlots[slot]=true;e.target.checked=true;toast('Keep at least one meal slot visible');return}commit()})}
  $('#showHomeStatsInput').addEventListener('change',e=>{state.settings.showHomeStats=e.target.checked;commit()});$('#showHomeFavoritesInput').addEventListener('change',e=>{state.settings.showHomeFavorites=e.target.checked;commit()});$('#showTomorrowPrepInput').addEventListener('change',e=>{state.settings.showTomorrowPrep=e.target.checked;commit()});$('#showHomeQuickActionsInput').addEventListener('change',e=>{state.settings.showHomeQuickActions=e.target.checked;commit()});$('#autoStapleGroceriesInput').addEventListener('change',e=>{state.settings.autoStapleGroceries=e.target.checked;if(e.target.checked)ensureRecurringStaples(true);commit()});$('#askPantryDeductInput').addEventListener('change',e=>{state.settings.askPantryDeductAfterCook=e.target.checked;commit()});
  $('#exportButton').addEventListener('click',exportBackup);$('#importInput').addEventListener('change',e=>importBackup(e.target.files?.[0]));$('#resetButton').addEventListener('click',()=>{if(confirm('Reset Bento and permanently clear all local recipes, plans, pantry items, groceries, leftovers, history and settings on this device?')){state=defaultState();persistNow();navigate('home');toast('Bento reset')}});
  $('#quickAddButton').addEventListener('click',()=>openDialog($('#quickAddDialog')));$('#brandButton').addEventListener('click',()=>navigate('about'));$('#searchButton').addEventListener('click',()=>{navigate('recipes');setTimeout(()=>$('#recipeSearch').focus(),80)});
  $('#menuButton').addEventListener('click',openMenu);$('#menuCloseButton').addEventListener('click',closeMenu);$('#menuBackdrop').addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#appMenu')?.classList.contains('open'))closeMenu()});

  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;$('#installButton').classList.remove('hidden')});$('#installButton').addEventListener('click',async()=>{if(!deferredInstallPrompt){toast('On iPhone: Share → Add to Home Screen');return}deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;$('#installButton').classList.add('hidden')});window.addEventListener('appinstalled',()=>toast('Bento installed ♡'));if(/iPhone|iPad|iPod/i.test(navigator.userAgent)&&!window.matchMedia('(display-mode: standalone)').matches)$('#installButton').classList.remove('hidden');

  ['gesturestart','gesturechange','gestureend'].forEach(type=>document.addEventListener(type,e=>e.preventDefault(),{passive:false}));document.addEventListener('touchstart',e=>{if(e.touches?.length>1)e.preventDefault()},{passive:false});let lastTouchEnd=0;document.addEventListener('touchend',e=>{const now=Date.now();if(now-lastTouchEnd<=300&&!e.target.closest('input,textarea,select'))e.preventDefault();lastTouchEnd=now},{passive:false});document.addEventListener('dragstart',e=>e.preventDefault());document.addEventListener('contextmenu',e=>{if(!e.target.closest('input,textarea'))e.preventDefault()});
  $$('dialog').forEach(d=>d.addEventListener('close',()=>{if(d.id==='recipeDetailDialog'){cookingSession=null;stopCookingTimer(false);releaseWakeLock()}}));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persistNow();else{if(cookingTimer)syncCookingTimer();if(cookingSession||document.body.classList.contains('shopping-mode'))requestWakeLock()}});window.addEventListener('pagehide',persistNow);
  if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));

  ensureRecurringStaples(false);
  const hash=location.hash.replace('#','');if(hash==='more')history.replaceState(null,'','#home');else if(hash&&document.querySelector(`.view[data-view="${hash}"]`))currentView=hash;applyTheme();navigate(currentView,false);
